package com.zenix.musicplayer;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.graphics.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import androidx.core.app.NotificationCompat;
import org.json.*;

/** Independent user-enabled character window; it never takes ownership of audio. */
public final class AssistantOverlayService extends Service {
    static final String OPEN_ASSISTANT_EXTRA="zenix.openAssistant";
    private static volatile boolean active;private static volatile AssistantOverlayService instance;
    static void refreshSkin(){AssistantOverlayService service=instance;if(service!=null)service.main.post(()->{if(!service.destroyed&&service.view!=null)service.view.load();});}
    private WindowManager manager;private WindowManager.LayoutParams params;private CharacterView view;private final java.util.concurrent.ExecutorService loader=java.util.concurrent.Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private boolean destroyed;
    private float downX,downY;private int startX,startY;private boolean moved,locked;private ZenixRuntime runtime;
    static boolean running(){return active;}
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(){super.onCreate();instance=this;runtime=ZenixRuntime.get(this);if(!Settings.canDrawOverlays(this)){stopSelf();return;}String channel="zenix-music-assistant";NotificationManager notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)notifications.createNotificationChannel(new NotificationChannel(channel,"音乐助手悬浮",NotificationManager.IMPORTANCE_LOW));PendingIntent close=PendingIntent.getService(this,2114,new Intent(this,AssistantOverlayService.class).setAction("close"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent home=PendingIntent.getActivity(this,2115,new Intent(this,MainActivity.class).putExtra(OPEN_ASSISTANT_EXTRA,true),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=new NotificationCompat.Builder(this,channel).setSmallIcon(R.drawable.zenix_icon).setContentTitle("Zenix 音乐助手").setContentText("轻触害羞回应，长按打开操作；可随时关闭").setContentIntent(home).setSilent(true).setOngoing(true).addAction(0,"关闭助手",close).build();if(Build.VERSION.SDK_INT>=34)startForeground(2113,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(2113,notification);manager=(WindowManager)getSystemService(WINDOW_SERVICE);params=new WindowManager.LayoutParams(dp(108),dp(144),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.START;params.x=dp(12);params.y=dp(180);view=new CharacterView();try{manager.addView(view,params);active=true;}catch(Exception error){stopSelf();return;}view.setOnLongClickListener(v->{menu();return true;});view.setOnTouchListener((v,event)->{switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:downX=event.getRawX();downY=event.getRawY();startX=params.x;startY=params.y;moved=false;return false;case MotionEvent.ACTION_MOVE:if(!locked&&(Math.abs(event.getRawX()-downX)>dp(5)||Math.abs(event.getRawY()-downY)>dp(5))){moved=true;view.cancelLongPress();view.setPressed(false);params.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-params.width,startX+(int)(event.getRawX()-downX)));params.y=Math.max(0,Math.min(getResources().getDisplayMetrics().heightPixels-params.height,startY+(int)(event.getRawY()-downY)));manager.updateViewLayout(view,params);return true;}break;case MotionEvent.ACTION_UP:if(moved)return true;break;}return false;});view.setOnClickListener(v->view.react());}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"close".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}if(params!=null&&intent!=null){int size=dp(Math.max(64,Math.min(220,intent.getIntExtra("size",108))));params.width=size;params.height=Math.round(size*4f/3f);manager.updateViewLayout(view,params);}return START_NOT_STICKY;}
    private void menu(){PopupMenu menu=new PopupMenu(this,view);for(String label:new String[]{"打开音乐助手","播放／暂停","上一首","下一首",locked?"解锁位置":"锁定位置","关闭助手"})menu.getMenu().add(label);menu.setOnMenuItemClickListener(item->{String label=item.getTitle().toString();try{if(label.equals("打开音乐助手"))startActivity(new Intent(this,MainActivity.class).putExtra(OPEN_ASSISTANT_EXTRA,true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));else if(label.equals("关闭助手"))stopSelf();else if(label.contains("位置"))locked=!locked;else if(runtime.service!=null){if(label.equals("播放／暂停"))runtime.service.toggle();else runtime.service.advance(label.equals("上一首")?-1:1);}}catch(Exception ignored){}return true;});menu.show();}
    @Override public void onDestroy(){active=false;instance=null;destroyed=true;main.removeCallbacksAndMessages(null);loader.shutdownNow();if(view!=null)try{manager.removeView(view);}catch(Exception ignored){}super.onDestroy();}
    @Override public IBinder onBind(Intent intent){return null;}
    private final class CharacterView extends View {
        private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private Bitmap[] poses=new Bitmap[4];private int pose,clicks,loadRevision;private final Runnable idle=()->{pose=0;invalidate();};
        CharacterView(){super(AssistantOverlayService.this);setContentDescription("Zenix 星音，拖动移动，轻触互动，长按操作");load();}
        void load(){final int revision=++loadRevision;loader.execute(()->{Bitmap[] next=new Bitmap[4];try{JSONObject saved=new AssistantFeatures(AssistantOverlayService.this).skin();if(saved!=null){JSONObject config=saved.getJSONObject("config"),animations=config.getJSONObject("animations"),images=saved.getJSONObject("images");JSONArray frames=config.getJSONArray("frames");String[] states={"idle","shy","greeting","listening"};for(int i=0;i<4;i++){JSONObject animation=animations.optJSONObject(states[i]);if(animation==null)animation=animations.getJSONObject("idle");byte[] bytes=android.util.Base64.decode(images.getString(frames.getString(animation.getJSONArray("frames").getInt(0))),android.util.Base64.NO_WRAP);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=Math.max(1,config.optInt("height",256)/384);next[i]=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(next[i]==null)throw new Exception("皮肤图片无法读取");}}else{String[] files={"zenix-muse.png","zenix-muse-shy.png","zenix-muse.png","zenix-muse-listening.png"};for(int i=0;i<4;i++)try(java.io.InputStream input=getAssets().open("zenix/assistant/"+files[i])){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=4;next[i]=BitmapFactory.decodeStream(input,null,options);}}}catch(Exception failure){for(Bitmap image:next)if(image!=null)image.recycle();next=new Bitmap[4];try(java.io.InputStream input=getAssets().open("zenix/assistant/zenix-muse.png")){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=4;next[0]=BitmapFactory.decodeStream(input,null,options);}catch(Exception ignored){}}
            final Bitmap[] ready=next;main.post(()->{if(destroyed||revision!=loadRevision){for(Bitmap image:ready)if(image!=null)image.recycle();return;}for(Bitmap image:poses)if(image!=null)image.recycle();poses=ready;invalidate();});});}
        void react(){pose=1+clicks++%3;main.removeCallbacks(idle);setContentDescription(pose==1?"星音害羞了":pose==2?"星音向你招手":"星音正在侧耳聆听");invalidate();main.postDelayed(idle,3000);}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);Bitmap image=poses[pose]!=null?poses[pose]:poses[0];if(image==null)return;float scale=Math.min(getWidth()/(float)image.getWidth(),getHeight()/(float)image.getHeight()),width=image.getWidth()*scale,height=image.getHeight()*scale;canvas.drawBitmap(image,null,new RectF((getWidth()-width)/2,(getHeight()-height)/2,(getWidth()+width)/2,(getHeight()+height)/2),paint);paint.setColor(Color.WHITE);paint.setTextSize(dp(10));paint.setTextAlign(Paint.Align.CENTER);paint.setShadowLayer(dp(2),0,0,Color.BLACK);canvas.drawText("Zenix",getWidth()/2f,getHeight()-dp(3),paint);paint.clearShadowLayer();}
        @Override protected void onDetachedFromWindow(){loadRevision++;main.removeCallbacks(idle);for(Bitmap image:poses)if(image!=null)image.recycle();poses=new Bitmap[4];super.onDetachedFromWindow();}
    }
}
